const iconMap = {
  pin: PinIcon,
  cap: CapIcon,
  chart: ChartIcon,
  search: SearchIcon,
  chat: ChatIcon,
  camera: CameraIcon,
  briefcase: BriefcaseIcon,
  code: CodeIcon,
  bank: BankIcon,
  research: ResearchIcon,
}

export function Icon({ name, ...props }) {
  const Component = iconMap[name]
  if (!Component) return null
  return <Component {...props} />
}
